const express = require('express');
// It is recommended to install and use the following libraries for enhanced security.
// Run 'npm install helmet express-rate-limit express-validator' to install them.
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Use helmet to set various HTTP headers for security
app.use(helmet());

// Enable rate limiting to prevent brute-force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply the rate limiting middleware to all requests
app.use(limiter);

// Middleware to parse JSON bodies
app.use(express.json());

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// New endpoint to get a user by ID, with input validation
app.get('/users/:id', (req, res) => {
  const { id } = req.params;
  // Basic validation: check if id is a number
  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid user ID. Must be a number.' });
  }

  // In a real app, you would fetch the user from a database.
  // For this example, we'll just return a dummy user.
  const user = { id: parseInt(id), name: 'User ' + id, email: `user${id}@example.com` };

  if (user) {
    res.json(user);
  } else {
    res.status(404).json({ error: 'User not found' });
  }
});

// New endpoint to demonstrate input validation for query parameters
app.get('/search', [
  // Validate that the 'q' query parameter is not empty
  body('q').not().isEmpty().withMessage('Search query cannot be empty'),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // In a real app, you would perform a search based on the query.
  // For this example, we'll just return a dummy message.
  res.json({ message: `Search results for "${req.query.q}"` });
});

