import os
import psycopg2
import requests
from dotenv import load_dotenv

def verify_database_connection(database_url):
    """Verifies the connection to the database."""
    print("\nVerifying database connection...")
    try:
        conn = psycopg2.connect(database_url)
        conn.close()
        print("✔️ Database connection successful.")
    except Exception as e:
        print(f"❌ Database connection failed: {e}")

def verify_aws_api_key(access_key_id, secret_access_key):
    """Verifies the AWS API key."""
    print("\nVerifying AWS API key...")
    try:
        # A simple, non-destructive AWS API call to verify credentials
        response = requests.post(
            "https://sts.amazonaws.com/",
            params={"Action": "GetCallerIdentity", "Version": "2011-06-15"},
            auth=(access_key_id, secret_access_key),
        )
        if response.status_code == 200:
            print("✔️ AWS API key is valid.")
        else:
            print(f"❌ AWS API key is invalid. Status code: {response.status_code}")
            print(f"   Response: {response.text}")
    except Exception as e:
        print(f"❌ AWS API key verification failed: {e}")

def verify_anthropic_api_key(api_key):
    """Verifies the Anthropic API key."""
    print("\nVerifying Anthropic API key...")
    try:
        response = requests.post(
            "https://api.anthropic.com/v1/messages",
            headers={"x-api-key": api_key, "content-type": "application/json", "anthropic-version": "2023-06-01"},
            json={"model": "claude-3-opus-20240229", "max_tokens": 1, "messages": [{"role": "user", "content": "."}]},
        )
        # A 400 Bad Request is expected for an empty prompt, which indicates the key is valid.
        if response.status_code == 400:
            print("✔️ Anthropic API key is valid.")
        else:
            print(f"❌ Anthropic API key is invalid. Status code: {response.status_code}")
            print(f"   Response: {response.text}")
    except Exception as e:
        print(f"❌ Anthropic API key verification failed: {e}")

def verify_stripe_api_key(api_key):
    """Verifies the Stripe API key."""
    print("\nVerifying Stripe API key...")
    try:
        response = requests.get(
            "https://api.stripe.com/v1/customers",
            auth=(api_key, "")
        )
        if response.status_code == 200:
            print("✔️ Stripe API key is valid.")
        else:
            print(f"❌ Stripe API key is invalid. Status code: {response.status_code}")
            print(f"   Response: {response.text}")
    except Exception as e:
        print(f"❌ Stripe API key verification failed: {e}")

if __name__ == "__main__":
    load_dotenv(dotenv_path=".env.test")

    database_url = os.getenv("DATABASE_URL")
    aws_access_key_id = os.getenv("AWS_ACCESS_KEY_ID")
    aws_secret_access_key = os.getenv("AWS_SECRET_ACCESS_KEY")
    anthropic_api_key = os.getenv("ANTHROPIC_API_KEY")
    stripe_secret_key = os.getenv("STRIPE_SECRET_KEY")

    if database_url:
        verify_database_connection(database_url)
    if aws_access_key_id and aws_secret_access_key:
        verify_aws_api_key(aws_access_key_id, aws_secret_access_key)
    if anthropic_api_key:
        verify_anthropic_api_key(anthropic_api_key)
    if stripe_secret_key:
        verify_stripe_api_key(stripe_secret_key)

